<script setup>
import { ref, computed, watch } from 'vue';
import { api, action, date, downloadFile } from '../api';
import { ElMessage, ElMessageBox } from 'element-plus';
import Markdown from './Markdown.vue';
const props=defineProps({book:{type:Object,required:true},disabled:{type:Boolean,default:false}}),emit=defineEmits(['changed']);
const panel=ref(''),versions=ref([]),snapshot=ref(null),shares=ref([]),origins=ref([]),suggestion=ref(null),busy=ref(false);
const share=ref({username:'',accessRole:'VIEWER'}),strategy=ref('semantic');
const owner=computed(()=>['OWNER','ADMIN'].includes(props.book.accessRole)),edit=computed(()=>owner.value||props.book.accessRole==='EDITOR');
let generation=0;
watch(()=>props.book.id,()=>{generation++;panel.value='';snapshot.value=null;});
async function open(name){panel.value=panel.value===name?'':name;if(!panel.value)return;const run=++generation;await action(async()=>{const result=await api(`/api/books/${props.book.id}/${name}`);if(run!==generation)return;if(name==='versions')versions.value=result;if(name==='shares')shares.value=result;if(name==='origin')origins.value=result;});}
async function preview(revision){await action(async()=>snapshot.value=await api(`/api/books/${props.book.id}/versions/${revision}`));}
async function restore(){try{await ElMessageBox.confirm(`将历史 v${snapshot.value.revision} 恢复为新修订，发布状态保持当前设置。`,'恢复历史内容',{confirmButtonText:'恢复内容',cancelButtonText:'取消'});}catch{return;}busy.value=true;await action(async()=>{const value=await api(`/api/books/${props.book.id}/versions/${snapshot.value.revision}/restore`,{method:'POST',body:{expectedRevision:props.book.revision}});emit('changed',value);snapshot.value=null;panel.value='';ElMessage.success('已生成新修订并加入索引队列');});busy.value=false;}
async function grant(){await action(async()=>{await api(`/api/books/${props.book.id}/shares`,{method:'PUT',body:share.value});shares.value=await api(`/api/books/${props.book.id}/shares`);share.value.username='';ElMessage.success('分享权限已保存');});}
async function revoke(id){await action(async()=>{await api(`/api/books/${props.book.id}/shares/${id}`,{method:'DELETE'});shares.value=await api(`/api/books/${props.book.id}/shares`);});}
async function suggest(){busy.value=true;await action(async()=>{suggestion.value=await api(`/api/books/${props.book.id}/suggest`,{method:'POST'});panel.value='organize';});busy.value=false;}
async function apply(){busy.value=true;await action(async()=>{emit('changed',await api(`/api/books/${props.book.id}/organize`,{method:'POST',body:suggestion.value}));panel.value='';suggestion.value=null;ElMessage.success('分类与标签已应用');});busy.value=false;}
async function reindex(){busy.value=true;await action(async()=>{await api(`/api/books/${props.book.id}/reindex?chunking=${strategy.value}`,{method:'POST'});emit('changed',await api(`/api/books/${props.book.id}`));ElMessage.success('已按所选策略重新索引');});busy.value=false;}
</script>
<template><div class="book-workspace-tools"><p v-if="disabled" class="muted">先保存当前编辑内容，再恢复历史版本或应用自动整理。</p><div class="workspace-toolbar"><span class="scope-label">{{owner?'我的 Book':edit?'已获得编辑权限':'只读分享'}}</span><button @click="open('versions')">历史版本</button><button v-if="owner" @click="open('shares')">分享权限</button><button @click="open('origin')">采集来源</button><button @click="action(()=>downloadFile(`/api/books/${book.id}/export?format=md`,`${book.title}.md`))">导出 Markdown</button><button @click="action(()=>downloadFile(`/api/books/${book.id}/export?format=pdf`,`${book.title}.pdf`))">导出 PDF</button><button v-if="edit" :disabled="busy||disabled" @click="suggest">自动分类与标签</button></div><section v-if="panel==='versions'" class="knowledge-panel"><h2>历史版本</h2><p class="muted">恢复会创建新修订；升级前没有保存过的修改无法追溯。</p><div class="version-layout"><ul class="version-list"><li v-for="v in versions" :key="v.revision"><button @click="preview(v.revision)">v{{v.revision}} · {{v.reason}}<small>{{date(v.createdAt)}} {{v.author}}</small></button></li></ul><div v-if="snapshot"><h3>{{snapshot.title}} · v{{snapshot.revision}}</h3><p v-if="!snapshot.content" class="muted">此版本内容来自原文件。恢复时会同时恢复对应文件。</p><Markdown v-else :content="snapshot.content"/><el-button v-if="edit" :disabled="busy||disabled||snapshot.revision===book.revision" @click="restore">恢复此版本</el-button></div><p v-else class="muted">选择版本，查看历史内容。</p></div></section><section v-if="panel==='shares'&&owner" class="knowledge-panel"><h2>分享给已注册用户</h2><form class="share-form" @submit.prevent="grant"><el-input v-model="share.username" aria-label="分享用户名" placeholder="用户名" required/><el-select v-model="share.accessRole" aria-label="分享权限"><el-option label="可阅读与提问" value="VIEWER"/><el-option label="可编辑正文" value="EDITOR"/></el-select><el-button native-type="submit" type="primary">保存分享</el-button></form><ul class="share-list"><li v-for="s in shares" :key="s.userId"><span>{{s.nickname}}（{{s.username}}） · {{s.accessRole==='EDITOR'?'可编辑':'可阅读'}}</span><button class="danger" @click="revoke(s.userId)">撤销</button></li></ul><p class="muted">发布、下线、删除和修改分享权限由所有者控制。</p></section><section v-if="panel==='origin'" class="knowledge-panel"><h2>来源与索引</h2><p v-if="!origins.length" class="muted">此 Book 来自在线编写或原文件上传。</p><div v-for="o in origins" :key="o.sourceUrl"><a :href="o.sourceUrl" target="_blank" rel="noopener noreferrer">{{o.sourceUrl}}</a><p class="muted">最近采集 {{date(o.fetchedAt)}}</p></div><div v-if="edit" class="share-form"><el-select v-model="strategy" aria-label="切片策略"><el-option value="semantic" label="语义边界切片"/><el-option value="sentence" label="固定长度与句子切片"/></el-select><el-button :loading="busy" :disabled="disabled" @click="reindex">按此策略重新索引</el-button></div></section><section v-if="panel==='organize'&&suggestion" class="knowledge-panel"><h2>整理建议</h2><p>分类：<strong>{{suggestion.suggestion.category}}</strong></p><p>标签：{{suggestion.suggestion.tags.join('、')}}</p><el-button type="primary" :loading="busy" :disabled="disabled" @click="apply">应用到当前修订</el-button><button @click="panel=''">暂不应用</button></section></div></template>
